$(document).ready(function(){$("#invoice-required").on('click',function(){let invoice_required=$("#invoice-required").is(':checked');$.ajax({type:'POST',headers:{"cache-control":"no-cache"},url:invoiceOptionUrl+'?rand='+new Date().getTime(),async:!0,cache:!1,dataType:"json",data:{ajax:!0,method:'toggleOption',token:invoiceOptionToken,invoice_required:invoice_required},success:function(jsonData){if(jsonData.status===!1){alert(jsonData.error)}else{$("#stock-notification-div").css({'display':'none'});$("#stock-notification-message").css({'display':'block'}).html('<p class="text-success"><i class="fa fa-bell"></i> در صورت تجدید موجودی به شما اطلاع خواهیم داد</p>')}},error:function(XMLHttpRequest,textStatus,errorThrown){}})})})